import{_ as s,C as i,o as d,c as l,a2 as r,j as e,a,E as n}from"./chunks/framework.BSl-aDiU.js";const v=JSON.parse('{"title":"1. Overview","description":"","frontmatter":{},"headers":[],"relativePath":"gdd/overview.md","filePath":"gdd/overview.md"}'),h={name:"gdd/overview.md"},g={id:"_1-1-pitch",tabindex:"-1"},p={id:"_1-5-art-direction",tabindex:"-1"};function c(u,t,f,m,b,y){const o=i("Badge");return d(),l("div",null,[t[6]||(t[6]=r('<h1 id="_1-overview" tabindex="-1">1. Overview <a class="header-anchor" href="#_1-overview" aria-label="Permalink to &quot;1. Overview&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Title</strong></td><td>Fighter Force</td></tr><tr><td><strong>Genre</strong></td><td>Puzzle · colour-matching auto-shooter</td></tr><tr><td><strong>Platform</strong></td><td>Web (mobile portrait first)</td></tr><tr><td><strong>Engine</strong></td><td>Phaser 4, TypeScript, Vite</td></tr><tr><td><strong>Session</strong></td><td>1–4 minutes per level</td></tr></tbody></table>',2)),e("h2",g,[t[0]||(t[0]=a("1.1 Pitch ",-1)),n(o,{type:"tip",text:"Live"}),t[1]||(t[1]=a()),t[2]||(t[2]=e("a",{class:"header-anchor",href:"#_1-1-pitch","aria-label":'Permalink to "1.1 Pitch <Badge type="tip" text="Live" />"'},"​",-1))]),t[7]||(t[7]=r('<p>A packed hangar of colour-coded fighter planes sits under an enemy armada. Tap a fighter to send it up to the flight zone, where it lines up under an enemy of <strong>its own colour</strong> and fires straight up. Enemies at the front shield the ones behind them, and every enemy shoots back at the flight zone, which has limited HP. Only fighters with a clear path out of the hangar can take off, and only 5 can fly at once. The puzzle is the <strong>order</strong>: launch the right colours for the front line in front of you, fast, and don&#39;t fill the sky with fighters that have nothing to shoot.</p><h2 id="_1-2-design-pillars" tabindex="-1">1.2 Design pillars <a class="header-anchor" href="#_1-2-design-pillars" aria-label="Permalink to &quot;1.2 Design pillars&quot;">​</a></h2><ol><li><strong>Every tap is a decision.</strong> The player never aims; all skill is in choosing which fighter to launch next, and launching it before enemy fire wears the flight zone down.</li><li><strong>Readable at a glance.</strong> Colour, a number (ammo on fighters, hit points on enemies) and a dimmed/bright state tell the whole story.</li><li><strong>Always fair.</strong> Every level is built so each colour&#39;s ammo exactly equals that colour&#39;s enemy hit points, and a solver proves every shipped level can be won (see <a href="./levels">Levels &amp; balance</a>).</li></ol><h2 id="_1-3-target-player" tabindex="-1">1.3 Target player <a class="header-anchor" href="#_1-3-target-player" aria-label="Permalink to &quot;1.3 Target player&quot;">​</a></h2><p>Casual mobile puzzle players who enjoy sort, jam and unblock games (one-thumb play, short sessions), plus a light shooter fantasy for visual payoff.</p><h2 id="_1-4-screen-at-a-glance" tabindex="-1">1.4 Screen at a glance <a class="header-anchor" href="#_1-4-screen-at-a-glance" aria-label="Permalink to &quot;1.4 Screen at a glance&quot;">​</a></h2><p>The 780 × 1688 portrait canvas is split top to bottom:</p><table tabindex="0"><thead><tr><th>Area</th><th>y range (px)</th><th>What happens there</th></tr></thead><tbody><tr><td>HUD</td><td>0–150</td><td>Level name, stage progress dots (BOSS badge), home and restart buttons</td></tr><tr><td>Enemy area</td><td>150–880</td><td>The current stage&#39;s enemies or boss</td></tr><tr><td>Flight zone</td><td>880–1060</td><td>Launched fighters line up and shoot; shows <code>n/5</code> (and the zone&#39;s HP bar when enemy fire is on)</td></tr><tr><td>Hangar board</td><td>1095–1660</td><td>The full grid of fighters, walls and elevators the player taps</td></tr></tbody></table>',8)),e("h2",p,[t[3]||(t[3]=a("1.5 Art direction ",-1)),n(o,{type:"tip",text:"Live"}),t[4]||(t[4]=a()),t[5]||(t[5]=e("a",{class:"header-anchor",href:"#_1-5-art-direction","aria-label":'Permalink to "1.5 Art direction <Badge type="tip" text="Live" />"'},"​",-1))]),t[8]||(t[8]=r('<p>Glossy arcade space shooter, in the style of mobile &quot;galaxy attack&quot; games: dark space, metallic ships, neon light.</p><table tabindex="0"><thead><tr><th>Element</th><th>Look</th></tr></thead><tbody><tr><td>Background</td><td>Deep navy-to-purple nebula with two star layers scrolling down at different speeds (18 and 55 px/s) for parallax</td></tr><tr><td>Fighters</td><td>Fighters that can launch idle with a gentle bob and burning engines. <strong>One colour tone only</strong>: fuselage, wings, canopy, guns and engine flame are all tints and shades of the fighter&#39;s colour (no grey, gold or blue). The ammo number only appears once the fighter is in the flight zone</td></tr><tr><td>Regular enemies</td><td>Bat-winged drones (small, medium) and spiked heavies (large): armour in the enemy&#39;s colour, dark metal body, glowing core, orange engine flames</td></tr><tr><td>Boss</td><td>One complete spaceship in one of three designs (raptor warship, mantis hive ship, dreadnought battle saucer), nose down. Each part is a section of the airframe painted in its colour (wings, central hull with reactor, nose, engines with flames, outer gun pods) on a dark metal hull. The guns on each section show its weapon (single, triple spread, long burst barrel, aimed twin barrels). Destroyed sections go dark and their engine flames go out</td></tr><tr><td>Bullets</td><td>Fighters fire neon plasma bolts in their colour, straight up; enemies would fire spinning glowing diamonds in theirs (enemy fire is off for now)</td></tr><tr><td>Effects</td><td>Additive light: muzzle flashes, hit sparks, explosions with a white core, coloured bloom, shockwave ring and sparks</td></tr><tr><td>Hangar and UI</td><td>Dark glass panels with chamfered corners and glowing cyan edges; landing-slot cells; walls are metal crates with hazard stripes; the flight zone is a cyan energy-shield band; stage progress is a row of dots with a BOSS badge in the HUD</td></tr><tr><td>Home screen</td><td>Just the title <strong>FIGHTER FORCE</strong> (with a cyan glow) over the hero fighter, and a <strong>PLAY</strong> button</td></tr><tr><td>Elevator</td><td>Metal lift shaft with a glowing chevron on the side it faces, its remaining count, and a dim preview of the next fighter</td></tr><tr><td>Mystery fighter</td><td>Near-black silhouette with a violet rim and a big &quot;?&quot;; reveals with a coloured flash</td></tr><tr><td>Frozen fighter</td><td>Translucent faceted ice block with cracks over the fighter and a large counter; shards fall at each count, and the block bursts at 0</td></tr><tr><td>Font</td><td>Russo One (Google Fonts), falling back to Arial Black</td></tr></tbody></table><p><strong>Colour is still the gameplay read:</strong> every ship, plate and bullet is painted in its gameplay colour, so the art never hides which fighter can hit what. All art is painted in code at start-up (<code>src/game/art.ts</code>) with the Canvas 2D API, so there are no image files to manage yet.</p>',3))])}const _=s(h,[["render",c]]);export{v as __pageData,_ as default};
